// Monochrome filmstrip sampled from the supplied success clip at 30 fps.
(function (global) {
  'use strict';
  if (customElements.get('leaves-success')) return;
  let sharedAudio;
  const film = new Image();
  film.src = 'data:image/png;base64,';
  const ready = film.decode().then(() => true, () => false);
  class LeavesSuccess extends HTMLElement {
    /** Call directly from a real click/tap. Returns false if sound is unavailable. */
    static async unlockAudio() {
      try {
        const AudioContext = global.AudioContext || global.webkitAudioContext;
        if (!AudioContext) return false;
        if (!sharedAudio || sharedAudio.state === 'closed') sharedAudio = new AudioContext();
        if (sharedAudio.state === 'running') return true;
        let timer;
        try {
          await Promise.race([
            sharedAudio.resume(),
            new Promise((resolve) => { timer = setTimeout(resolve, 400); })
          ]);
        } finally { clearTimeout(timer); }
        return sharedAudio.state === 'running';
      } catch (_) { return false; }
    }


    constructor() {
      super();
      this._nodes = [];
      const shadow = this.attachShadow({mode: 'open'});
      shadow.innerHTML = '<style>:host{display:grid;place-items:center}canvas{display:block;width:48px;height:48px}</style><canvas width="96" height="96" aria-hidden="true"></canvas>';
      this.canvas = shadow.querySelector('canvas');
    }

    async play({sound = true, volume = .4} = {}) {
      const context = this.canvas.getContext('2d');
      if (!context || !(await ready)) throw Error('無法繪製登入動畫');
      const reduced = global.matchMedia('(prefers-reduced-motion: reduce)').matches;
      let previous, elapsed = 0, lastFrame = -1, sounded = false;
      return new Promise(resolve => {
        const paint = now => {
          if (!this.isConnected) { resolve(); return; }
          // Begin on the first paint. A busy login callback cannot skip the ring.
          if (previous !== undefined) elapsed += Math.min(40, Math.max(0, now - previous));
          previous = now;
          const frame = reduced ? 35 : Math.min(35, Math.floor(elapsed * .03));
          if (frame !== lastFrame) {
            context.clearRect(0, 0, 96, 96);
            context.drawImage(film, frame * 96, 0, 96, 96, 0, 0, 96, 96);
            lastFrame = frame;
          }
          if (!sounded && (reduced || elapsed >= 570)) {
            sounded = true;
            if (sound && sharedAudio?.state === 'running') {
              try { this._scheduleAudio(sharedAudio.currentTime, volume); }
              catch { this._stopAudio(); }
            }
          }
          if (elapsed >= (reduced ? 350 : 1520)) resolve();
          else requestAnimationFrame(paint);
        };
        requestAnimationFrame(paint);
      });
    }
    disconnectedCallback() { this._stopAudio(); }
    _scheduleAudio(start, volume) {
      const ctx = sharedAudio;
      if (!ctx || ctx.state !== 'running') return false;
      const voices = [
        { at: 0, frequency: 987.7666, strength: 1 },
        { at: 0.13, frequency: 1318.5102, strength: 1.12 }
      ];
      const ratios = [1, 2.01, 3.92];
      const amplitudes = [0.20, 0.07, 0.025];
      const decays = [0.22, 0.12, 0.065];
      voices.forEach((voice) => {
        ratios.forEach((ratio, i) => {
          const oscillator = ctx.createOscillator();
          const envelope = ctx.createGain();
          const onset = start + voice.at;
          const peak = amplitudes[i] * voice.strength * volume;
          oscillator.type = 'sine';
          oscillator.frequency.value = voice.frequency * ratio;
          envelope.gain.setValueAtTime(0, onset);
          envelope.gain.linearRampToValueAtTime(peak, onset + 0.005);
          // Exponential decay to silence; no sampled or downloaded sound.
          envelope.gain.setTargetAtTime(0, onset + 0.005, decays[i]);
          envelope.gain.setValueAtTime(peak * Math.exp(-0.855 / decays[i]), onset + 0.86);
          envelope.gain.linearRampToValueAtTime(0, onset + 0.88);
          oscillator.connect(envelope);
          envelope.connect(ctx.destination);
          const node = { oscillator, envelope };
          this._nodes.push(node);
          oscillator.onended = () => {
            oscillator.disconnect();
            envelope.disconnect();
            const index = this._nodes.indexOf(node);
            if (index >= 0) this._nodes.splice(index, 1);
          };
          oscillator.start(onset);
          oscillator.stop(onset + 0.885);
        });
      });
      return true;
    }

    _stopAudio() {
      const nodes = this._nodes.splice(0);
      nodes.forEach(({ oscillator, envelope }) => {
        oscillator.onended = null;
        try { oscillator.stop(); } catch (_) { /* May already have ended. */ }
        oscillator.disconnect();
        envelope.disconnect();
      });
    }

  }
  global.LeavesSuccess = LeavesSuccess;
  customElements.define('leaves-success', LeavesSuccess);
})(window);
